BianHao::BianHao() :
    theDlxFileName(NULL),
    theDialog(NULL),
    point0(NULL),
    point01(NULL),
    styleCircle(NULL),
    styleTriangleDown(NULL),
    styleHexagon(NULL),
    styleRoundedBox(NULL),
    styleUnderline(NULL),
    styleNoSymbol(NULL),
    styleCircleBar(NULL),
    styleTriangleDownBar(NULL),
    styleHexagonBar(NULL),
    styleRoundedBoxBar(NULL),
    styleUnderlineBar(NULL),
    styleNoSymbolBar(NULL),
    textSource(NULL),
    attributeName(NULL),
    balloonSize(NULL),
    textHeight(NULL),
    automaticMode(NULL),
    draftingViewSelection(NULL),
    idSymbolBuilder1(NULL),
    selectedBalloonType(NXOpen::Annotations::BalloonTypesRoundedBox),
    cachedLeaderTarget(NULL),
    cachedLeaderView(NULL),
    cachedPartObject(NULL),
    cachedBodyObject(NULL),
    cachedFirstPoint(0.0, 0.0, 0.0),
    cachedSecondPoint(0.0, 0.0, 0.0),
    cachedUpperText(""),
    cachedCommittedSymbol(NULL),
    hasPreviewCache(false),
    hasSecondPointCache(false),
    rememberedTextSourceValue(0),
    rememberedAttributeName("名称"),
    restoringDialogState(false)
{
    try
    {
        // Initialize the NX Open C++ API environment
        BianHao::theSession = NXOpen::Session::GetSession();
        BianHao::theUI = UI::GetUI();
        const std::string dlxPath = zhihui_embedded_dialog::ExtractDlxToRandomPath(IDR_ZH_DLX_BIANHAO_DLX);

        if (dlxPath.empty())

        {

            throw std::runtime_error("BianHao dialog resource is missing.");

        }

        theDlxFileName = NULL;

        theDialog = BianHao::theUI->CreateDialog(dlxPath.c_str());
        // Registration of callback functions
        theDialog->AddApplyHandler(make_callback(this, &BianHao::apply_cb));
        theDialog->AddOkHandler(make_callback(this, &BianHao::ok_cb));
        theDialog->AddUpdateHandler(make_callback(this, &BianHao::update_cb));
        theDialog->AddInitializeHandler(make_callback(this, &BianHao::initialize_cb));
        theDialog->AddDialogShownHandler(make_callback(this, &BianHao::dialogShown_cb));
    }
    catch(exception&)
    {
        //---- Enter your exception handling code here -----
        throw;
    }
}

